{"command":"python3 -c '
with open("true.html", "r") as f: content = f.read()

import re
bytes_div = content[content.find("<div id=\x27bytes\x27>"):content.find("<div id=\x27ascii\x27>")]

# Let us parse line by line and track open spans at each byte
lines = bytes_div.split("\n")

current_spans = []
byte_idx = 0

for line_num, line in enumerate(lines):
    # Find all tags in this line
    pos = 0
    while pos < len(line):
        if line[pos] == "<":
            end = line.find(">", pos)
            tag = line[pos:end+1]
            if tag.startswith("<span"):
                cls = re.search(r"class=\x27([^\x27]*)\x27", tag).group(1)
                current_spans.append(cls)
            elif tag == "</span>":
                current_spans.pop()
            pos = end + 1
        elif line[pos:pos+6] == "&nbsp;":
            pos += 6 # &nbsp; part of magic byte
        else:
            # Check if this is a hex byte (2 hex chars)
            m = re.match(r"[0-9a-fA-F]{2}", line[pos:])
            if m:
                # We reached a byte!
                if byte_idx < 120 or byte_idx in [790, 791, 792, 793, 25010, 25016]:
                    print(f"Byte {byte_idx} (0x{byte_idx:x}): {current_spans}")
                byte_idx += 1
                pos += 2
            else:
                pos += 1

print("Total bytes parsed:", byte_idx)
'"}

