{"command":"cat <<'EOF' > src/elf.rs
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Class {
    Bit32,
    Bit64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Endianness {
    Little,
    Big,
}

pub fn read_u16(bytes: &[u8], offset: usize, endian: Endianness) -> u16 {
    let buf = [bytes[offset], bytes[offset + 1]];
    match endian {
        Endianness::Little => u16::from_le_bytes(buf),
        Endianness::Big => u16::from_be_bytes(buf),
    }
}

pub fn read_u32(bytes: &[u8], offset: usize, endian: Endianness) -> u32 {
    let buf = [
        bytes[offset],
        bytes[offset + 1],
        bytes[offset + 2],
        bytes[offset + 3],
    ];
    match endian {
        Endianness::Little => u32::from_le_bytes(buf),
        Endianness::Big => u32::from_be_bytes(buf),
    }
}

pub fn read_u64(bytes: &[u8], offset: usize, endian: Endianness) -> u64 {
    let buf = [
        bytes[offset],
        bytes[offset + 1],
        bytes[offset + 2],
        bytes[offset + 3],
        bytes[offset + 4],
        bytes[offset + 5],
        bytes[offset + 6],
        bytes[offset + 7],
    ];
    match endian {
        Endianness::Little => u64::from_le_bytes(buf),
        Endianness::Big => u64::from_be_bytes(buf),
    }
}

#[derive(Debug, Clone)]
pub struct ElfHeader {
    pub class: Class,
    pub endianness: Endianness,
    pub osabi: u8,
    pub abiversion: u8,
    pub e_type: u16,
    pub e_machine: u16,
    pub e_version: u32,
    pub e_entry: u64,
    pub e_phoff: u64,
    pub e_shoff: u64,
    pub e_flags: u32,
    pub e_ehsize: u16,
    pub e_phentsize: u16,
    pub e_phnum: u16,
    pub e_shentsize: u16,
    pub e_shnum: u16,
    pub e_shstrndx: u16,
}

#[derive(Debug, Clone)]
pub struct ProgramHeader {
    pub p_type: u32,
    pub p_flags: u32,
    pub p_offset: u64,
    pub p_vaddr: u64,
    pub p_paddr: u64,
    pub p_filesz: u64,
    pub p_memsz: u64,
    pub p_align: u64,
    pub offset_in_file: usize,
}

#[derive(Debug, Clone)]
pub struct SectionHeader {
    pub index: usize,
    pub sh_name: u32,
    pub sh_type: u32,
    pub sh_flags: u64,
    pub sh_addr: u64,
    pub sh_offset: u64,
    pub sh_size: u64,
    pub sh_link: u32,
    pub sh_info: u32,
    pub sh_addralign: u64,
    pub sh_entsize: u64,
    pub name: String,
    pub offset_in_file: usize,
}

#[derive(Debug)]
pub struct ElfFile {
    pub header: ElfHeader,
    pub program_headers: Vec<ProgramHeader>,
    pub section_headers: Vec<SectionHeader>,
}

impl ElfFile {
    pub fn parse(bytes: &[u8]) -> Result<ElfFile, String> {
        if bytes.len() < 16 {
            return Err("file is smaller than ELF header's e_ident".to_string());
        }

        if &bytes[0..4] != b"\x7fELF" {
            return Err("mismatched magic: not an ELF file".to_string());
        }

        let class = match bytes[4] {
            1 => Class::Bit32,
            2 => Class::Bit64,
            v => return Err(format!("Unknown bitness: {}", v)),
        };

        let endianness = match bytes[5] {
            1 => Endianness::Little,
            2 => Endianness::Big,
            v => return Err(format!("Unknown endianness: {}", v)),
        };

        let min_header_size = match class {
            Class::Bit32 => 52,
            Class::Bit64 => 64,
        };

        if bytes.len() < min_header_size {
            return Err("file is smaller than ELF file header".to_string());
        }

        let osabi = bytes[7];
        let abiversion = bytes[8];

        let e_type = read_u16(bytes, 16, endianness);
        let e_machine = read_u16(bytes, 18, endianness);
        let e_version = read_u32(bytes, 20, endianness);

        let (e_entry, e_phoff, e_shoff, e_flags, e_ehsize, e_phentsize, e_phnum, e_shentsize, e_shnum, e_shstrndx) =
            match class {
                Class::Bit32 => (
                    read_u32(bytes, 24, endianness) as u64,
                    read_u32(bytes, 28, endianness) as u64,
                    read_u32(bytes, 32, endianness) as u64,
                    read_u32(bytes, 36, endianness),
                    read_u16(bytes, 40, endianness),
                    read_u16(bytes, 42, endianness),
                    read_u16(bytes, 44, endianness),
                    read_u16(bytes, 46, endianness),
                    read_u16(bytes, 48, endianness),
                    read_u16(bytes, 50, endianness),
                ),
                Class::Bit64 => (
                    read_u64(bytes, 24, endianness),
                    read_u64(bytes, 32, endianness),
                    read_u64(bytes, 40, endianness),
                    read_u32(bytes, 48, endianness),
                    read_u16(bytes, 52, endianness),
                    read_u16(bytes, 54, endianness),
                    read_u16(bytes, 56, endianness),
                    read_u16(bytes, 58, endianness),
                    read_u16(bytes, 60, endianness),
                    read_u16(bytes, 62, endianness),
                ),
            };

        let header = ElfHeader {
            class,
            endianness,
            osabi,
            abiversion,
            e_type,
            e_machine,
            e_version,
            e_entry,
            e_phoff,
            e_shoff,
            e_flags,
            e_ehsize,
            e_phentsize,
            e_phnum,
            e_shentsize,
            e_shnum,
            e_shstrndx,
        };

        // Parse program headers
        let mut program_headers = Vec::new();
        if e_phnum > 0 && e_phoff > 0 {
            for i in 0..e_phnum as usize {
                let off = e_phoff as usize + i * e_phentsize as usize;
                if off + e_phentsize as usize <= bytes.len() {
                    let ph = match class {
                        Class::Bit32 => ProgramHeader {
                            p_type: read_u32(bytes, off, endianness),
                            p_offset: read_u32(bytes, off + 4, endianness) as u64,
                            p_vaddr: read_u32(bytes, off + 8, endianness) as u64,
                            p_paddr: read_u32(bytes, off + 12, endianness) as u64,
                            p_filesz: read_u32(bytes, off + 16, endianness) as u64,
                            p_memsz: read_u32(bytes, off + 20, endianness) as u64,
                            p_flags: read_u32(bytes, off + 24, endianness),
                            p_align: read_u32(bytes, off + 28, endianness) as u64,
                            offset_in_file: off,
                        },
                        Class::Bit64 => ProgramHeader {
                            p_type: read_u32(bytes, off, endianness),
                            p_flags: read_u32(bytes, off + 4, endianness),
                            p_offset: read_u64(bytes, off + 8, endianness),
                            p_vaddr: read_u64(bytes, off + 16, endianness),
                            p_paddr: read_u64(bytes, off + 24, endianness),
                            p_filesz: read_u64(bytes, off + 32, endianness),
                            p_memsz: read_u64(bytes, off + 40, endianness),
                            p_align: read_u64(bytes, off + 48, endianness),
                            offset_in_file: off,
                        },
                    };
                    program_headers.push(ph);
                }
            }
        }

        // Parse section headers raw
        struct RawShdr {
            index: usize,
            sh_name: u32,
            sh_type: u32,
            sh_flags: u64,
            sh_addr: u64,
            sh_offset: u64,
            sh_size: u64,
            sh_link: u32,
            sh_info: u32,
            sh_addralign: u64,
            sh_entsize: u64,
            offset_in_file: usize,
        }

        let mut raw_shdrs = Vec::new();
        if e_shnum > 0 && e_shoff > 0 {
            for i in 0..e_shnum as usize {
                let off = e_shoff as usize + i * e_shentsize as usize;
                if off + e_shentsize as usize <= bytes.len() {
                    let sh = match class {
                        Class::Bit32 => RawShdr {
                            index: i,
                            sh_name: read_u32(bytes, off, endianness),
                            sh_type: read_u32(bytes, off + 4, endianness),
                            sh_flags: read_u32(bytes, off + 8, endianness) as u64,
                            sh_addr: read_u32(bytes, off + 12, endianness) as u64,
                            sh_offset: read_u32(bytes, off + 16, endianness) as u64,
                            sh_size: read_u32(bytes, off + 20, endianness) as u64,
                            sh_link: read_u32(bytes, off + 24, endianness),
                            sh_info: read_u32(bytes, off + 28, endianness),
                            sh_addralign: read_u32(bytes, off + 32, endianness) as u64,
                            sh_entsize: read_u32(bytes, off + 36, endianness) as u64,
                            offset_in_file: off,
                        },
                        Class::Bit64 => RawShdr {
                            index: i,
                            sh_name: read_u32(bytes, off, endianness),
                            sh_type: read_u32(bytes, off + 4, endianness),
                            sh_flags: read_u64(bytes, off + 8, endianness),
                            sh_addr: read_u64(bytes, off + 16, endianness),
                            sh_offset: read_u64(bytes, off + 24, endianness),
                            sh_size: read_u64(bytes, off + 32, endianness),
                            sh_link: read_u32(bytes, off + 40, endianness),
                            sh_info: read_u32(bytes, off + 44, endianness),
                            sh_addralign: read_u64(bytes, off + 48, endianness),
                            sh_entsize: read_u64(bytes, off + 56, endianness),
                            offset_in_file: off,
                        },
                    };
                    raw_shdrs.push(sh);
                }
            }
        }

        // Get shstrtab offset and size
        let mut shstrtab_bytes: &[u8] = &[];
        if (e_shstrndx as usize) < raw_shdrs.len() {
            let shstr = &raw_shdrs[e_shstrndx as usize];
            let start = shstr.sh_offset as usize;
            let end = start + shstr.sh_size as usize;
            if end <= bytes.len() {
                shstrtab_bytes = &bytes[start..end];
            }
        }

        let section_headers = raw_shdrs
            .into_iter()
            .map(|raw| {
                let name = if (raw.sh_name as usize) < shstrtab_bytes.len() {
                    let slice = &shstrtab_bytes[raw.sh_name as usize..];
                    if let Some(null_pos) = slice.iter().position(|&b| b == 0) {
                        String::from_utf8_lossy(&slice[..null_pos]).to_string()
                    } else {
                        String::from_utf8_lossy(slice).to_string()
                    }
                } else {
                    String::new()
                };

                SectionHeader {
                    index: raw.index,
                    sh_name: raw.sh_name,
                    sh_type: raw.sh_type,
                    sh_flags: raw.sh_flags,
                    sh_addr: raw.sh_addr,
                    sh_offset: raw.sh_offset,
                    sh_size: raw.sh_size,
                    sh_link: raw.sh_link,
                    sh_info: raw.sh_info,
                    sh_addralign: raw.sh_addralign,
                    sh_entsize: raw.sh_entsize,
                    name,
                    offset_in_file: raw.offset_in_file,
                }
            })
            .collect();

        Ok(ElfFile {
            header,
            program_headers,
            section_headers,
        })
    }
}

