                    let sh = match class {
                        Class::Bit32 => RawShdr {
                            index: i,
                            sh_name: read_u32(bytes, off, endianness),
                            sh_type: read_u32(bytes, off + 4, endianness),
                            sh_flags: read_u32(bytes, off + 8, endianness) as u64,
                            sh_addr: read_u32(bytes, off + 12, endianness) as u64,
                            sh_offset: read_u32(bytes, off + 16, endianness) as u64,
                            sh_size: read_u32(bytes, off + 20, endianness) as u64,
                            sh_link: read_u32(bytes, off + 24, endianness),
                            sh_info: read_u32(bytes, off + 28, endianness),
                            sh_addralign: read_u32(bytes, off + 32, endianness) as u64,
                            sh_entsize: read_u32(bytes, off + 36, endianness) as u64,
                            offset_in_file: off,
                        },
                        Class::Bit64 => RawShdr {
                            index: i,
                            sh_name: read_u32(bytes, off, endianness),
                            sh_type: read_u32(bytes, off + 4, endianness),
                            sh_flags: read_u64(bytes, off + 8, endianness),
                            sh_addr: read_u64(bytes, off + 16, endianness),
                            sh_offset: read_u64(bytes, off + 24, endianness),
                            sh_size: read_u64(bytes, off + 32, endianness),
                            sh_link: read_u32(bytes, off + 40, endianness),
                            sh_info: read_u32(bytes, off + 44, endianness),
                            sh_addralign: read_u64(bytes, off + 48, endianness),
                            sh_entsize: read_u64(bytes, off + 56, endianness),
                            offset_in_file: off,
                        },
                    };
                    raw_shdrs.push(sh);
                }
            }
        }

        // Get shstrtab offset and size
        let mut shstrtab_bytes: &[u8] = &[];
        if (e_shstrndx as usize) < raw_shdrs.len() {
            let shstr = &raw_shdrs[e_shstrndx as usize];
            let start = shstr.sh_offset as usize;
            let end = start + shstr.sh_size as usize;
            if end <= bytes.len() {
                shstrtab_bytes = &bytes[start..end];
            }
        }

        let section_headers = raw_shdrs
            .into_iter()
            .map(|raw| {
                let name = if (raw.sh_name as usize) < shstrtab_bytes.len() {
                    let slice = &shstrtab_bytes[raw.sh_name as usize..];
                    if let Some(null_pos) = slice.iter().position(|&b| b == 0) {
                        String::from_utf8_lossy(&slice[..null_pos]).to_string()
                    } else {
                        String::from_utf8_lossy(slice).to_string()
                    }
                } else {
                    String::new()
                };

                SectionHeader {
                    index: raw.index,
                    sh_name: raw.sh_name,
                    sh_type: raw.sh_type,
                    sh_flags: raw.sh_flags,
                    sh_addr: raw.sh_addr,
                    sh_offset: raw.sh_offset,
                    sh_size: raw.sh_size,
                    sh_link: raw.sh_link,
                    sh_info: raw.sh_info,
                    sh_addralign: raw.sh_addralign,
                    sh_entsize: raw.sh_entsize,
                    name,
                    offset_in_file: raw.offset_in_file,
                }
            })
            .collect();

        Ok(ElfFile {
            header,
            program_headers,
            section_headers,
        })
    }
}

