pub fn phdr_flags_string(p_flags: u32) -> String {
    let mut s = String::new();
    if p_flags & 4 != 0 {
        s.push('R');
    }
    if p_flags & 2 != 0 {
        s.push('W');
    }
    if p_flags & 1 != 0 {
        s.push('X');
    }
    s
}

