pub fn shdr_flags_string(sh_flags: u64) -> String {
    let mut s = String::new();
    if sh_flags & 1 != 0 {
        s.push('W');
    }
    if sh_flags & 2 != 0 {
        s.push('A');
    }
    if sh_flags & 4 != 0 {
        s.push('X');
    }
    if s.is_empty() {
        "0".to_string()
    } else {
        s
    }
}

pub fn human_file_size(size: u64) -> String {
    if size < 1024 {
        format!("{} B", size)
    } else if size < 1024 * 1024 {
        format!("{:.1} KiB ({} B)", size as f64 / 1024.0, size)
    } else if size < 1024 * 1024 * 1024 {
        format!("{:.1} MiB ({} B)", size as f64 / (1024.0 * 1024.0), size)
    } else {
        format!("{:.1} GiB ({} B)", size as f64 / (1024.0 * 1024.0 * 1024.0), size)
    }
}

pub fn fmt_size_cell(size: u64) -> String {
    if size < 1024 {
        format!("{}", size)
    } else if size < 1024 * 1024 {
        format!("{} ({:.1} KiB)", size, size as f64 / 1024.0)
    } else if size < 1024 * 1024 * 1024 {
        format!("{} ({:.1} MiB)", size, size as f64 / (1024.0 * 1024.0))
    } else {
        format!("{} ({:.1} GiB)", size, size as f64 / (1024.0 * 1024.0 * 1024.0))
    }
}
