bytes_div = content[content.find("<div id=\x27bytes\x27>"):content.find("<div id=\x27ascii\x27>")]

with open("/bin/true", "rb") as f: raw_bytes = f.read()

phoff = int.from_bytes(raw_bytes[32:40], "little")
phnum = int.from_bytes(raw_bytes[56:58], "little")
phentsize = int.from_bytes(raw_bytes[54:56], "little")

phdrs = []
for i in range(phnum):
    off = phoff + i * phentsize
    ptype = int.from_bytes(raw_bytes[off:off+4], "little")
    pflags = int.from_bytes(raw_bytes[off+4:off+8], "little")
    poff = int.from_bytes(raw_bytes[off+8:off+16], "little")
    pfilesz = int.from_bytes(raw_bytes[off+32:off+40], "little")
    phdrs.append({"index": i, "type": ptype, "offset": poff, "filesz": pfilesz, "start": off})

shoff = int.from_bytes(raw_bytes[40:48], "little")
shnum = int.from_bytes(raw_bytes[60:62], "little")
shentsize = int.from_bytes(raw_bytes[58:60], "little")

shdrs = []
for i in range(shnum):
    off = shoff + i * shentsize
    stype = int.from_bytes(raw_bytes[off+4:off+8], "little")
    soff = int.from_bytes(raw_bytes[off+24:off+32], "little")
    ssize = int.from_bytes(raw_bytes[off+32:off+40], "little")
    shdrs.append({"index": i, "type": stype, "offset": soff, "size": ssize, "start": off})

def get_spans(idx):
    stack = []
    ehsize = 64
    if idx < ehsize:
        stack.append("ehdr")
        if idx < 16:
            stack.append("ident")
            if idx < 4: stack.append("magic")
            elif idx == 4: stack.append("class")
            elif idx == 5: stack.append("data")
            elif idx == 6: stack.append("ver")
            elif idx == 7: stack.append("abi")
            elif idx == 8: stack.append("abi_ver")
            else: stack.append("pad")
        else:
            m = {
                (16,18): "e_type", (18,20): "e_machine", (20,24): "e_version",
                (24,32): "e_entry", (32,40): "e_phoff", (40,48): "e_shoff",
                (48,52): "e_flags", (52,54): "e_ehsize", (54,56): "e_phentsize",
                (56,58): "e_phnum", (58,60): "e_shentsize", (60,62): "e_shnum",
                (62,64): "e_shstrndx"
            }
            for (s,e), tag in m.items():
                if s <= idx < e:
                    stack.append(tag)
                    break
        return stack

    # All matching segments (p_offset != 0 and p_filesz > 0)
    matching_segs = []
    for ph in phdrs:
        if ph["filesz"] > 0 and ph["offset"] != 0:
            if ph["offset"] <= idx < ph["offset"] + ph["filesz"]:
                matching_segs.append(ph["index"])

    for s_idx in matching_segs:
        stack.append("bin_segment" + str(s_idx) + " segment")

    matching_phdr = None
    for ph in phdrs:
        if ph["start"] <= idx < ph["start"] + phentsize:
            matching_phdr = ph
            break

    matching_shdr = None
    for sh in shdrs:
        if sh["start"] <= idx < sh["start"] + shentsize:
            matching_shdr = sh
            break

    matching_sec = None
    for sh in shdrs:
        if sh["type"] != 8 and sh["size"] > 0:
            if sh["offset"] <= idx < sh["offset"] + sh["size"]:
                matching_sec = sh
                break

    if matching_phdr:
        p_i = matching_phdr["index"]
        p_start = matching_phdr["start"]
        stack.append("bin_phdr" + str(p_i) + " phdr")
        m = {(0,4): "p_type", (4,8): "p_flags", (8,16): "p_offset", (16,24): "p_vaddr", (24,32): "p_paddr", (32,40): "p_filesz", (40,48): "p_memsz", (48,56): "p_align"}
        for (s,e), tag in m.items():
            if s <= idx - p_start < e:
                stack.append(tag)
                break
    elif matching_shdr:
        s_i = matching_shdr["index"]
        s_start = matching_shdr["start"]
        stack.append("bin_shdr" + str(s_i) + " shdr")
        m = {(0,4): "sh_name", (4,8): "sh_type", (8,16): "sh_flags", (16,24): "sh_addr", (24,32): "sh_offset", (32,40): "sh_size", (40,44): "sh_link", (44,48): "sh_info", (48,56): "sh_addralign", (56,64): "sh_entsize"}
        for (s,e), tag in m.items():
            if s <= idx - s_start < e:
                stack.append(tag)
                break
    elif matching_sec:
        stack.append("bin_section" + str(matching_sec["index"]) + " section hover")
        if len(matching_segs) > 1:
            stack.append("segment_subrange hover")

    return stack

out = ["<div id=\x27bytes\x27>"]
active_spans = []

i = 0
while i < len(raw_bytes):
    target_spans = get_spans(i)

    common_len = 0
    while common_len < len(active_spans) and common_len < len(target_spans) and active_spans[common_len] == target_spans[common_len]:
        common_len += 1

    while len(active_spans) > common_len:
        out.append("</span>")
        active_spans.pop()

    if i > 0:
        if i % 16 == 0:
            out.append("\n")
        else:
            out.append(" ")

    while len(active_spans) < len(target_spans):
        new_cls = target_spans[len(active_spans)]
        out.append(f"<span class=\x27{new_cls}\x27>")
        active_spans.append(new_cls)

    if i == 0 and raw_bytes[0:4] == b"\x7fELF":
        out.append("7f &nbsp;E &nbsp;L &nbsp;F")
        i += 4
    else:
        out.append(f"{raw_bytes[i]:02x}")
        i += 1

while len(active_spans) > 0:
    out.append("</span>")
    active_spans.pop()

out.append("</div>")
gen = "".join(out)

print("Equal?", gen == bytes_div)
if gen != bytes_div:
    import difflib
    diff = list(difflib.unified_diff(bytes_div.splitlines(), gen.splitlines(), lineterm=""))
    print("Diff lines:", len(diff))
    print("\n".join(diff[:10]))
