fn html_escape(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&apos;")
}

fn render_notes(note_bytes: &[u8], endianness: Endianness, html: &mut String) {
    let mut pos = 0;
    while pos + 12 <= note_bytes.len() {
        let namesz = read_u32(note_bytes, pos, endianness) as usize;
        let descsz = read_u32(note_bytes, pos + 4, endianness) as usize;
        let ntype = read_u32(note_bytes, pos + 8, endianness);

        let pad_name = (namesz + 3) & !3;
        let pad_desc = (descsz + 3) & !3;

        let name_start = pos + 12;
        let name_end = name_start + namesz;
        let desc_start = name_start + pad_name;
        let desc_end = desc_start + descsz;

        if desc_end > note_bytes.len() {
            break;
        }

        let raw_name = &note_bytes[name_start..name_end];
        let name_str = std::str::from_utf8(raw_name)
            .unwrap_or("")
            .trim_matches('\0');

        let desc_bytes = &note_bytes[desc_start..desc_end];

        html.push_str("            <tr><td><br></td></tr>\n");
        html.push_str(&format!(
            "            <tr> <td>Name:</td> <td>{}</td> </tr>\n",
            html_escape(name_str)
        ));
        html.push_str(&format!(
            "            <tr> <td>Type:</td> <td>0x{:x}</td> </tr>\n",
            ntype
        ));

        if name_str == "GNU" && ntype == 3 {
            let build_id: String = desc_bytes.iter().map(|b| format!("{:02x}", b)).collect();
            html.push_str(&format!(
                "            <tr> page Build ID:</td> <td>{}</td> </tr>\n",
                build_id
            ).replace("page Build ID:", "Build ID:"));
        } else {
            html.push_str("            <tr> <td>Desc:</td> <td>");
            for b in desc_bytes {
                html.push_str(&format!("<b>{:02x}</b> ", b));
            }
            html.push_str("</td> </tr>\n");
        }

        pos = desc_start + pad_desc;
    }
}

