                    .unwrap_or("")
                    .split('\0')
                    .filter(|s| !s.is_empty())
                    .collect();

                if !strings.is_empty() {
                    html.push_str("            <tr><td><br></td></tr>\n");
                    html.push_str("            <tr>\n              <td></td>\n              <td>\n                <div>\n");
                    for s in strings {
