use crate::elf::*;
use crate::templates::*;
use std::path::Path;

fn html_escape(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&apos;")
}

fn render_notes(note_bytes: &[u8], endianness: Endianness, html: &mut String) {
    let mut pos = 0;
    let mut is_first = true;
    while pos + 12 <= note_bytes.len() {
        let namesz = read_u32(note_bytes, pos, endianness) as usize;
        let descsz = read_u32(note_bytes, pos + 4, endianness) as usize;
        let ntype = read_u32(note_bytes, pos + 8, endianness);

        if namesz == 0 && descsz == 0 && ntype == 0 {
            break;
        }

        let pad_name = (namesz + 3) & !3;
        let pad_desc = (descsz + 3) & !3;

        let name_start = pos + 12;
        let name_end = name_start + namesz;
        let desc_start = name_start + pad_name;
        let desc_end = desc_start + descsz;

        if desc_end > note_bytes.len() {
            break;
        }

        let raw_name = &note_bytes[name_start..name_end];
        let name_str = std::str::from_utf8(raw_name)
            .unwrap_or("")
            .trim_matches('\0');

        let desc_bytes = &note_bytes[desc_start..desc_end];

        if is_first {
            html.push_str("            <tr><td><br></td></tr>\n");
            is_first = false;
        } else {
            html.push_str("            <tr> <td><br></td> </tr>\n");
        }

        html.push_str(&format!(
            "            <tr> <td>Name:</td> <td>{}</td> </tr>\n",
            html_escape(name_str)
        ));
        html.push_str(&format!(
            "            <tr> <td>Type:</td> <td>0x{:x}</td> </tr>\n",
            ntype
        ));

        if name_str == "GNU" && ntype == 3 {
            let build_id: String = desc_bytes.iter().map(|b| format!("{:02x}", b)).collect();
            html.push_str(&format!(
                "            <tr> <td>Build ID:</td> <td>{}</td> </tr>\n",
                build_id
            ));
        } else {
            html.push_str("            <tr> <td>Desc:</td> <td>");
            for b in desc_bytes {
                html.push_str(&format!("<b>{:02x}</b> ", b));
            }
            html.push_str("</td> </tr>\n");
        }

        pos = desc_start + pad_desc;
    }
}

pub fn generate_report(filename_arg: &str, raw_bytes: &[u8], elf: &ElfFile) -> String {
    let mut html = String::with_capacity(raw_bytes.len() * 10);

    let basename = Path::new(filename_arg)
        .file_name()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_else(|| filename_arg.to_string());

    // Head
    html.push_str("<!doctype html>\n<html>\n  <head>\n    <meta charset='utf-8'>\n    <meta name='viewport' content='width=900, initial-scale=1'>\n    <title>");
    html.push_str(&html_escape(&basename));
    html.push_str("</title>\n    <style>");
    html.push_str(STYLE);
    html.push_str("</style>\n  </head>\n  <body>");
    html.push_str(BODY_PRELUDE);

    // Table 1 (fileinfo)
    html.push_str("<table>\n");
    html.push_str(&format!(
        "      <tr class='fileinfo_file_name'> <td>File name:</td> <td>{}</td> </tr>\n",
        html_escape(filename_arg)
    ));
    html.push_str(&format!(
        "      <tr class='fileinfo_file_size'> <td>File size:</td> <td>{}</td> </tr>\n",
        human_file_size(raw_bytes.len() as u64)
    ));
    html.push_str(&format!(
        "      <tr class='fileinfo_class'> <td>Object class:</td> <td>{}</td> </tr>\n",
        match elf.header.class {
            Class::Bit32 => "32-bit",
            Class::Bit64 => "64-bit",
        }
    ));
    html.push_str(&format!(
        "      <tr class='fileinfo_data'> <td>Data encoding:</td> <td>{}</td> </tr>\n",
        match elf.header.endianness {
            Endianness::Little => "Little endian",
            Endianness::Big => "Big endian",
        }
    ));

    if elf.header.osabi == 0 {
        html.push_str("      <tr class='fileinfo_abi'> <td>ABI:</td> <td>SysV</td> </tr>\n");
    } else {
        html.push_str(&format!(
            "      <tr class='fileinfo_abi'> <td>Uncommon ABI(!):</td> <td>{}</td> </tr>\n",
            abi_name_string(elf.header.osabi)
        ));
        html.push_str(&format!(
            "      <tr class='fileinfo_abi_ver'> <td>ABI version:</td> <td>{}</td> </tr>\n",
            elf.header.abiversion
        ));
    }

    html.push_str(&format!(
        "      <tr class='fileinfo_e_type'> <td>Type:</td> <td>{}</td> </tr>\n",
        type_name_string(elf.header.e_type)
    ));
    html.push_str(&format!(
        "      <tr class='fileinfo_e_machine'> <td>Architecture:</td> <td>{}</td> </tr>\n",
        machine_name_string(elf.header.e_machine)
    ));
    html.push_str(&format!(
        "      <tr class='fileinfo_e_entry'> <td>Entrypoint:</td> <td><span class='number' title='{}'>0x{:x}</span></td> </tr>\n",
        elf.header.e_entry, elf.header.e_entry
    ));
    html.push_str(&format!(
        "      <tr class='fileinfo_ph'> <td>Program headers:</td> <td><span title='0x{:x}' class='number fileinfo_e_phnum'>{}</span> * <span title='0x{:x}' class='number fileinfo_e_phentsize'>{}</span> @ <span title='0x{:x}' class='number fileinfo_e_phoff'>{}</span></td> </tr>\n",
        elf.header.e_phnum, elf.header.e_phnum,
        elf.header.e_phentsize, elf.header.e_phentsize,
        elf.header.e_phoff, elf.header.e_phoff
    ));
    html.push_str(&format!(
        "      <tr class='fileinfo_sh'> <td>Section headers:</td> <td><span title='0x{:x}' class='number fileinfo_e_shnum'>{}</span> * <span title='0x{:x}' class='number fileinfo_e_shentsize'>{}</span> @ <span title='0x{:x}' class='number fileinfo_e_shoff'>{}</span></td> </tr>\n",
        elf.header.e_shnum, elf.header.e_shnum,
        elf.header.e_shentsize, elf.header.e_shentsize,
        elf.header.e_shoff, elf.header.e_shoff
    ));
    html.push_str("    </table>\n    ");

    // Offsets div
    html.push_str("<div id='offsets'>");
    let num_rows = (raw_bytes.len() + 15) / 16;
    for row in 0..num_rows {
        if row > 0 {
            html.push('\n');
        }
        html.push_str(&format!("{:x}", row * 16));
    }
    html.push_str("</div>\n    ");

    // Bytes div
    html.push_str("<div id='bytes'>");
    let mut active_spans: Vec<String> = Vec::new();

    let mut idx = 0;
    while idx < raw_bytes.len() {
        let target_spans = get_span_stack(idx, elf);

        let mut common_len = 0;
        while common_len < active_spans.len()
            && common_len < target_spans.len()
            && active_spans[common_len] == target_spans[common_len]
        {
            common_len += 1;
        }

        while active_spans.len() > common_len {
            html.push_str("</span>");
            active_spans.pop();
        }

        if idx > 0 {
            if idx % 16 == 0 {
                html.push('\n');
            } else {
                html.push(' ');
            }
        }

        while active_spans.len() < target_spans.len() {
            let new_cls = &target_spans[active_spans.len()];
            html.push_str("<span class='");
            html.push_str(new_cls);
            html.push_str("'>");
            active_spans.push(new_cls.clone());
        }

        if idx == 0 && raw_bytes.len() >= 4 && &raw_bytes[0..4] == b"\x7fELF" {
            html.push_str("7f &nbsp;E &nbsp;L &nbsp;F");
            idx += 4;
        } else {
            html.push_str(&format!("{:02x}", raw_bytes[idx]));
            idx += 1;
        }
    }

    while !active_spans.is_empty() {
        html.push_str("</span>");
        active_spans.pop();
    }
    html.push_str("</div>\n    ");

    // ASCII div
    html.push_str("<div id='ascii'>");
    for (i, &b) in raw_bytes.iter().enumerate() {
        if i > 0 && i % 16 == 0 {
            html.push('\n');
        }
        if (0x21..=0x7e).contains(&b) {
            let c = b as char;
            match c {
                '&' => html.push_str("&amp;"),
                '<' => html.push_str("&lt;"),
                '>' => html.push_str("&gt;"),
                '"' => html.push_str("&quot;"),
                '\'' => html.push_str("&apos;"),
                _ => html.push(c),
            }
        } else {
            html.push('.');
        }
    }
    html.push_str("</div>\n    ");

    // Sticky table
    html.push_str("<table id='sticky_table' cellspacing='0'>\n");
    html.push_str("      <tr>\n        <td id='desc'></td>\n        <td class='infotables'>\n");

    // info_phdr tables
    for (i, ph) in elf.program_headers.iter().enumerate() {
        html.push_str(&format!(
            "          <table class='conceal itable' id='info_phdr{}'>\n",
            i
        ));
        html.push_str("          <th colspan='2' class='phdr_itable'></th>\n");
        html.push_str(&format!(
            "            <tr> <td>Type:</td> <td>{}</td> </tr>\n",
            phdr_type_string(ph.p_type)
        ));
        html.push_str(&format!(
            "            <tr> <td>Flags:</td> <td>{}</td> </tr>\n",
            phdr_flags_string(ph.p_flags)
        ));
        html.push_str(&format!(
            "            <tr> <td>Offset in file:</td> <td><span class='number' title='{}'>0x{:x}</span></td> </tr>\n",
            ph.p_offset, ph.p_offset
        ));
        html.push_str(&format!(
            "            <tr> <td>Size in file:</td> <td><span class='number' title='0x{:x}'>{}</span></td> </tr>\n",
            ph.p_filesz,
            fmt_size_cell(ph.p_filesz)
        ));
        html.push_str(&format!(
            "            <tr> <td>Vaddr in memory:</td> <td><span class='number' title='{}'>0x{:x}</span></td> </tr>\n",
            ph.p_vaddr, ph.p_vaddr
        ));
        html.push_str(&format!(
            "            <tr> <td>Size in memory:</td> <td><span class='number' title='0x{:x}'>{}</span></td> </tr>\n",
            ph.p_memsz,
            fmt_size_cell(ph.p_memsz)
        ));
        html.push_str(&format!(
            "            <tr> <td>Alignment:</td> <td><span class='number' title='{}'>0x{:x}</span></td> </tr>\n",
            ph.p_align, ph.p_align
        ));
        html.push_str("          </table>\n");
    }

    // info_shdr tables
    for sh in &elf.section_headers {
        html.push_str(&format!(
            "          <table class='conceal itable' id='info_shdr{}'>\n",
            sh.index
        ));
        html.push_str("          <th colspan='2' class='shdr_itable'></th>\n");
        html.push_str(&format!(
            "            <tr> <td>Index:</td> <td>{}</td> </tr>\n",
            sh.index
        ));
        html.push_str(&format!(
            "            <tr> <td>Name:</td> <td>{}</td> </tr>\n",
            html_escape(&sh.name)
        ));
        html.push_str(&format!(
            "            <tr> <td>Type:</td> <td>{}</td>  host\n",
            shdr_type_string(sh.sh_type)
        ).replace(" host\n", "\n"));
        html.push_str(&format!(
            "            <tr> <td>Flags:</td> <td>{}</td> </tr>\n",
            shdr_flags_string(sh.sh_flags)
        ));
        html.push_str(&format!(
            "            <tr> <td>Vaddr in memory:</td> <td><span class='number' title='{}'>0x{:x}</span></td> </tr>\n",
            sh.sh_addr, sh.sh_addr
        ));
        html.push_str(&format!(
            "            <tr> <td>Offset in file:</td> <td><span class='number' title='{}'>0x{:x}</span></td> </tr>\n",
            sh.sh_offset, sh.sh_offset
        ));
        html.push_str(&format!(
            "            <tr> <td>Size in file:</td> <td><span class='number' title='0x{:x}'>{}</span></td> </tr>\n",
            sh.sh_size,
            fmt_size_cell(sh.sh_size)
        ));
        html.push_str(&format!(
            "            <tr> <td>Linked section:</td> <td>{}</td> </tr>\n",
            sh.sh_link
        ));
        html.push_str(&format!(
            "            <tr> <td>Extra info:</td> <td><span class='number' title='0x{:x}'>{}</span></td> </tr>\n",
            sh.sh_info, sh.sh_info
        ));
        html.push_str(&format!(
            "            <tr> <td>Alignment:</td> <td><span class='number' title='{}'>0x{:x}</span></td> </tr>\n",
            sh.sh_addralign, sh.sh_addralign
        ));
        html.push_str(&format!(
            "            <tr> <td>Size of entries:</td> <td><span class='number' title='0x{:x}'>{}</span></td> </tr>\n",
            sh.sh_entsize, sh.sh_entsize
        ));
        html.push_str("          </table>\n");
    }

    html.push_str("        </td>\n        <td class='infotables'>\n");

    // Precompute note range for SHT_NOTE sections
    let note_sections: Vec<&SectionHeader> = elf
        .section_headers
        .iter()
        .filter(|sh| sh.sh_type == 7)
        .collect();

    let note_start_opt = note_sections.iter().map(|sh| sh.sh_offset as usize).min();
    let note_end_opt = note_sections
        .iter()
        .map(|sh| (sh.sh_offset + sh.sh_size) as usize)
        .max();

    // info_segment tables
    for (i, ph) in elf.program_headers.iter().enumerate() {
        html.push_str(&format!(
            "          <table class='conceal itable' id='info_segment{}'>\n",
            i
        ));
        html.push_str("          <th colspan='2' class='segment_itable'></th>\n");
        html.push_str(&format!(
            "            <tr> <td>Type:</td> <td>{}</td> </tr>\n",
            phdr_type_string(ph.p_type)
        ));
        html.push_str(&format!(
            "            <tr> <td>Size in file:</td> <td><span class='number' title='0x{:x}'>{}</span></td> </tr>\n",
            ph.p_filesz,
            fmt_size_cell(ph.p_filesz)
        ));
        html.push_str(&format!(
            "            <tr> <td>Size in memory:</td> <td><span class='number' title='0x{:x}'>{}</span></td> </tr>\n",
            ph.p_memsz,
            fmt_size_cell(ph.p_memsz)
        ));

        // PT_INTERP segment
        if ph.p_type == 3 {
            let start = ph.p_offset as usize;
            let end = start + ph.p_filesz as usize;
            if end <= raw_bytes.len() {
                let interp_bytes = &raw_bytes[start..end];
                let interp_str = std::str::from_utf8(interp_bytes)
                    .unwrap_or("")
                    .trim_matches('\0');
                html.push_str("            <tr><td><br></td></tr>\n");
                html.push_str(&format!(
                    "            <tr> <td>Interpreter:</td> <td>{}</td> </tr>\n",
                    html_escape(interp_str)
                ));
            }
        }

        // PT_NOTE segment
        if ph.p_type == 4 {
            let start = ph.p_offset as usize;
            let end = if let (Some(s), Some(e)) = (note_start_opt, note_end_opt) {
                if start >= s && start < e {
                    e
                } else {
                    start + ph.p_filesz as usize
                }
            } else {
                start + ph.p_filesz as usize
            };

            if end <= raw_bytes.len() {
                render_notes(&raw_bytes[start..end], elf.header.endianness, &mut html);
            }
        }

        html.push_str("          </table>\n");
    }

    // info_section tables
    for sh in &elf.section_headers {
        html.push_str(&format!(
            "          <table class='conceal itable' id='info_section{}'>\n",
            sh.index
        ));
        html.push_str("          <th colspan='2' class='section_itable'></th>\n");
        html.push_str(&format!(
            "            <tr> <td>Type:</td> <td>{}</td> </tr>\n",
            shdr_type_string(sh.sh_type)
        ));
        html.push_str(&format!(
            "            <tr> <td>Size:</td> <td><span class='number' title='0x{:x}'>{}</span></td> </tr>\n",
            sh.sh_size,
            fmt_size_cell(sh.sh_size)
        ));

        // STRTAB section string preview
        if sh.sh_type == 3 {
            let start = sh.sh_offset as usize;
            let end = start + sh.sh_size as usize;
            if end <= raw_bytes.len() {
                let sec_bytes = &raw_bytes[start..end];
                let strings: Vec<&str> = std::str::from_utf8(sec_bytes)
                    .unwrap_or("")
                    .split('\0')
                    .filter(|s| !s.is_empty())
                    .collect();

                if !strings.is_empty() {
                    html.push_str("            <tr><td><br></td></tr>\n");
                    html.push_str("            <tr>\n              <td></td>\n              <td>\n                <div>\n");
                    for s in strings {
                        html.push_str("                  ");
                        html.push_str(&html_escape(s));
                        html.push('\n');
                    }
                    html.push_str("                </div>\n              </td>\n            </tr>\n");
                }
            }
        }

        html.push_str("          </table>\n");
    }

    html.push_str("        </td>\n      </tr>\n    </table>\n    ");

    // Script 0
    html.push_str(SCRIPT_0);
    html.push_str("\n    ");

    // Script 1
    html.push_str(SCRIPT_1);
    html.push_str("\n    ");

    // Script 2
    html.push_str(SCRIPT_2);
    html.push_str("\n    ");

    // Script 3
    html.push_str(&format!(
        "<script type='text/javascript'>\n      let fileLen = {}\n",
        raw_bytes.len()
    ));
    html.push_str("      function populateOffsets(columns) {\n");
    html.push_str("          let rows = Math.ceil(fileLen / columns);\n");
    html.push_str("          let elements = \"\";\n");
    html.push_str("          let offset = 0;\n\n");
    html.push_str("          for (let i = 0; i < rows; ++i) {\n");
    html.push_str("              elements += offset.toString(16) + \"</br>\\n\";\n");
    html.push_str("              offset += columns;\n");
    html.push_str("          }\n\n");
    html.push_str("          document.getElementById('offsets').innerHTML = elements;\n");
    html.push_str("      }\n    </script>\n    ");

    // Script 4
    html.push_str(SCRIPT_4_PRELUDE);
    html.push_str("\n      connect('.e_phoff', '.bin_phdr0');\n");
    html.push_str("      connect('.e_shoff', '.bin_shdr0');\n");

    for (i, _) in elf.program_headers.iter().enumerate() {
        html.push_str(&format!(
            "      connect('.bin_phdr{} > .p_offset', '.bin_segment{}');\n",
            i, i
        ));
    }

    for sh in &elf.section_headers {
        html.push_str(&format!(
            "      connect('.bin_shdr{} > .sh_offset', '.bin_section{}');\n",
            sh.index, sh.index
        ));
        if sh.sh_link != 0 {
            html.push_str(&format!(
                "      connect('.bin_shdr{} > .sh_link', '.bin_shdr{}');\n",
                sh.index, sh.sh_link
            ));
        }
    }

    html.push_str("      pushArrowElems();\n    </script>\n    ");

    // Script 5
    html.push_str(SCRIPT_5);
    html.push_str("\n  </body>\n</html>\n");

    html
}

fn get_span_stack(idx: usize, elf: &ElfFile) -> Vec<String> {
    let mut stack = Vec::new();

    let ehsize = elf.header.e_ehsize as usize;

    // 1. Is idx in ELF Header?
    if idx < ehsize {
        stack.push("ehdr".to_string());
        if idx < 16 {
            stack.push("ident".to_string());
            if idx < 4 {
                stack.push("magic".to_string());
            } else if idx == 4 {
                stack.push("class".to_string());
            } else if idx == 5 {
                stack.push("data".to_string());
            } else if idx == 6 {
                stack.push("ver".to_string());
            } else if idx == 7 {
                stack.push("abi".to_string());
            } else if idx == 8 {
                stack.push("abi_ver".to_string());
            } else {
                stack.push("pad".to_string());
            }
        } else {
            match elf.header.class {
                Class::Bit32 => match idx {
                    16..=17 => stack.push("e_type".to_string()),
                    18..=19 => stack.push("e_machine".to_string()),
                    20..=23 => stack.push("e_version".to_string()),
                    24..=27 => stack.push("e_entry".to_string()),
                    28..=31 => stack.push("e_phoff".to_string()),
                    32..=35 => stack.push("e_shoff".to_string()),
                    36..=39 => stack.push("e_flags".to_string()),
                    40..=41 => stack.push("e_ehsize".to_string()),
                    42..=43 => stack.push("e_phentsize".to_string()),
                    44..=45 => stack.push("e_phnum".to_string()),
                    46..=47 => stack.push("e_shentsize".to_string()),
                    48..=49 => stack.push("e_shnum".to_string()),
                    50..=51 => stack.push("e_shstrndx".to_string()),
                    _ => {}
                },
                Class::Bit64 => match idx {
                    16..=17 => stack.push("e_type".to_string()),
                    18..=19 => stack.push("e_machine".to_string()),
                    20..=23 => stack.push("e_version".to_string()),
                    24..=31 => stack.push("e_entry".to_string()),
                    32..=39 => stack.push("e_phoff".to_string()),
                    40..=47 => stack.push("e_shoff".to_string()),
                    48..=51 => stack.push("e_flags".to_string()),
                    52..=53 => stack.push("e_ehsize".to_string()),
                    54..=55 => stack.push("e_phentsize".to_string()),
                    56..=57 => stack.push("e_phnum".to_string()),
                    58..=59 => stack.push("e_shentsize".to_string()),
                    60..=61 => stack.push("e_shnum".to_string()),
                    62..=63 => stack.push("e_shstrndx".to_string()),
                    _ => {}
                },
            }
        }
        return stack;
    }

    // Matching segments
    let mut matching_segs: Vec<(usize, &ProgramHeader)> = elf
        .program_headers
        .iter()
        .enumerate()
        .filter(|(_, ph)| ph.p_filesz > 0 && ph.p_offset != 0)
        .filter(|(_, ph)| {
            let start = ph.p_offset as usize;
            let end = start + ph.p_filesz as usize;
            idx >= start && idx < end
        })
        .collect();

    matching_segs.sort_by(|(_, a), (_, b)| {
        b.p_filesz
            .cmp(&a.p_filesz)
            .then_with(|| a.offset_in_file.cmp(&b.offset_in_file))
    });

    for (seg_i, _) in &matching_segs {
        stack.push(format!("bin_segment{} segment", seg_i));
    }

    // Find phdr entry covering idx
    let mut matching_phdr = None;
    for (i, ph) in elf.program_headers.iter().enumerate() {
        let start = ph.offset_in_file;
        let end = start + elf.header.e_phentsize as usize;
        if idx >= start && idx < end {
            matching_phdr = Some((i, ph, start));
            break;
        }
    }

    // Find shdr entry covering idx
    let mut matching_shdr = None;
    for sh in &elf.section_headers {
        let start = sh.offset_in_file;
        let end = start + elf.header.e_shentsize as usize;
        if idx >= start && idx < end {
            matching_shdr = Some((sh, start));
            break;
        }
    }

    // Find section body covering idx
    let mut matching_section = None;
    for sh in &elf.section_headers {
        if sh.sh_type != 8 && sh.sh_size > 0 {
            let start = sh.sh_offset as usize;
            let end = start + sh.sh_size as usize;
            if idx >= start && idx < end {
                matching_section = Some(sh);
                break;
            }
        }
    }

    if let Some((p_i, _, p_start)) = matching_phdr {
        stack.push(format!("bin_phdr{} phdr", p_i));
        let field_tag = match elf.header.class {
            Class::Bit32 => match idx - p_start {
                0..=3 => "p_type",
                4..=7 => "p_offset",
                8..=11 => "p_vaddr",
                12..=15 => "p_paddr",
                16..=19 => "p_filesz",
                20..=23 => "p_memsz",
                24..=27 => "p_flags",
                28..=31 => "p_align",
                _ => "",
            },
            Class::Bit64 => match idx - p_start {
                0..=3 => "p_type",
                4..=7 => "p_flags",
                8..=15 => "p_offset",
                16..=23 => "p_vaddr",
                24..=31 => "p_paddr",
                32..=39 => "p_filesz",
                40..=47 => "p_memsz",
                48..=55 => "p_align",
                _ => "",
            },
        };
        if !field_tag.is_empty() {
            stack.push(field_tag.to_string());
        }
    } else if let Some((sh, s_start)) = matching_shdr {
        stack.push(format!("bin_shdr{} shdr", sh.index));
        let field_tag = match elf.header.class {
            Class::Bit32 => match idx - s_start {
                0..=3 => "sh_name",
                4..=7 => "sh_type",
                8..=11 => "sh_flags",
                12..=15 => "sh_addr",
                16..=19 => "sh_offset",
                20..=23 => "sh_size",
                24..=27 => "sh_link",
                28..=31 => "sh_info",
                32..=35 => "sh_addralign",
                36..=39 => "sh_entsize",
                _ => "",
            },
            Class::Bit64 => match idx - s_start {
                0..=3 => "sh_name",
                4..=7 => "sh_type",
                8..=15 => "sh_flags",
                16..=23 => "sh_addr",
                24..=31 => "sh_offset",
                32..=39 => "sh_size",
                40..=43 => "sh_link",
                44..=47 => "sh_info",
                48..=55 => "sh_addralign",
                56..=63 => "sh_entsize",
                _ => "",
            },
        };
        if !field_tag.is_empty() {
            stack.push(field_tag.to_string());
        }
    } else if let Some(sh) = matching_section {
        stack.push(format!("bin_section{} section hover", sh.index));
        if matching_segs
            .iter()
            .any(|(_, ph)| ph.p_type == 4 || ph.p_type == 0x6474e553)
        {
            stack.push("segment_subrange hover".to_string());
        }
    }

    stack
}
