    ));
    html.push_str("    </table>\n    ");

    // Offsets div
    html.push_str("<div id='offsets'>");
    let num_rows = (raw_bytes.len() + 15) / 16;
    for row in 0..num_rows {
        if row > 0 {
            html.push('\n');
